(function (){"use strict";const prefersReduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;function activateAsyncFonts(){const links = document.querySelectorAll('link[data-async-font]');links.forEach((link) =>{if (link.media !== "all"){link.media = "all";}});}function initTheme(){const raw = localStorage.getItem("eo_theme") || localStorage.getItem("theme");let savedTheme = "night";if (raw === "paper" || raw === "light"){savedTheme = "paper";}const root = document.documentElement;if (root.getAttribute("data-theme") !== savedTheme){root.setAttribute("data-theme",savedTheme);}const toggles = document.querySelectorAll(".theme-toggle-btn");toggles.forEach((btn) =>{btn.addEventListener("click",() =>{const current = root.getAttribute("data-theme") || "night";const next = current === "night" ? "paper" : "night";root.setAttribute("data-theme",next);localStorage.setItem("eo_theme",next);btn.setAttribute("aria-label",`Switch to ${next === "night" ? "light" : "dark"} mode`);});});}function initLagosClock(){const clockEls = document.querySelectorAll(".lagos-clock");if (!clockEls.length) return;let formatter = null;try{formatter = new Intl.DateTimeFormat("en-GB",{timeZone: "Africa/Lagos",hour: "2-digit",minute: "2-digit",second: "2-digit",hour12: false});}catch (e){formatter = null;}function update(){if (document.hidden) return;const now = new Date();const timeStr = formatter ? formatter.format(now) : `${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")}`;const label = `${timeStr} WAT`;for (let i = 0;i < clockEls.length;i++){if (clockEls[i].textContent !== label){clockEls[i].textContent = label;}}}update();setInterval(update,1000);}function initRoleRotator(){if (prefersReduced) return;const rotatorCell = document.querySelector(".rotator-cell");if (!rotatorCell) return;const words = rotatorCell.querySelectorAll(".rotator-word");if (words.length <= 1) return;let currentIndex = 0;const intervalMs = 2800;setInterval(() =>{if (document.hidden) return;const prevWord = words[currentIndex];currentIndex = (currentIndex + 1) % words.length;const nextWord = words[currentIndex];for (let i = 0;i < words.length;i++){if (words[i] !== prevWord){words[i].classList.remove("is-exiting");}}prevWord.classList.remove("is-active");prevWord.classList.add("is-exiting");prevWord.setAttribute("aria-hidden","true");nextWord.classList.add("is-active");nextWord.setAttribute("aria-hidden","false");},intervalMs);}function initWorksCarousel(){const track = document.querySelector(".works-carousel-track");if (!track) return;const cards = track.querySelectorAll(".works-card");const prevBtn = document.querySelector(".carousel-prev-btn");const nextBtn = document.querySelector(".carousel-next-btn");const counterDisplay = document.querySelector(".carousel-index-display");const totalCount = cards.length;if (totalCount === 0) return;let cachedStride = 504;if ("ResizeObserver" in window){const ro = new ResizeObserver((entries) =>{if (entries[0]){const cardW = entries[0].contentRect.width;if (cardW > 0){cachedStride = cardW + 24;}}});ro.observe(cards[0]);}if (counterDisplay){counterDisplay.textContent = `01 / 0${totalCount}`;}let scrollRaf = 0;function updateIndex(){scrollRaf = 0;const activeIdx = Math.min(Math.round(track.scrollLeft / cachedStride),totalCount - 1);if (counterDisplay){const text = `0${Math.max(0, activeIdx) + 1} / 0${totalCount}`;if (counterDisplay.textContent !== text){counterDisplay.textContent = text;}}}if (prevBtn){prevBtn.addEventListener("click",() =>{track.scrollBy({left: -cachedStride,behavior: prefersReduced ? "auto" : "smooth"});});}if (nextBtn){nextBtn.addEventListener("click",() =>{track.scrollBy({left: cachedStride,behavior: prefersReduced ? "auto" : "smooth"});});}track.addEventListener( "scroll",() =>{if (!scrollRaf){scrollRaf = requestAnimationFrame(updateIndex);}},{passive: true});}function initMobileDrawer(){const menuBtn = document.querySelector(".menu-toggle-btn");const drawer = document.querySelector(".mobile-drawer");if (!menuBtn || !drawer) return;function closeDrawer(){drawer.classList.remove("is-open");menuBtn.setAttribute("aria-expanded","false");document.body.style.overflow = "";}menuBtn.addEventListener("click",() =>{if (drawer.classList.contains("is-open")){closeDrawer();}else{drawer.classList.add("is-open");menuBtn.setAttribute("aria-expanded","true");document.body.style.overflow = "hidden";}});const drawerLinks = drawer.querySelectorAll("a");drawerLinks.forEach((link) =>{link.addEventListener("click",closeDrawer);});document.addEventListener("keydown",(e) =>{if (e.key === "Escape" && drawer.classList.contains("is-open")){closeDrawer();menuBtn.focus();}});}function initFooterYear(){const yearEls = document.querySelectorAll("#footer-year, .current-year");if (!yearEls.length) return;const year = String(new Date().getFullYear());yearEls.forEach((el) =>{if (el.textContent !== year){el.textContent = year;}});}activateAsyncFonts();document.addEventListener("DOMContentLoaded",() =>{initTheme();initLagosClock();initRoleRotator();initWorksCarousel();initMobileDrawer();initFooterYear();});})();